// Expand compact data into full catalog entries
export function getWTrafficCatalog() {
  const catalog = [];
  for (const [sIdx, path, name, len] of WT_IMGS) {
    const s = WT_SERIES[sIdx];
    catalog.push({
      id: 'wt-' + path.replace(/[^a-zA-Z0-9]/g, '_').substring(0, 70),
      name: name,
      category: _C[s.c] || s.c,
      traction: _T[s.t] || s.t,
      maxSpeed: s.v,
      mass: s.m,
      power: s.p,
      passengerCapacity: s.pax,
      freightCapacity: s.frt,
      length: len || s.l,
      imageData: 'https://raw.githubusercontent.com/pespotteur-byte/RAIL-EMPIRE-APP/devin/1780231310-catalog-bb7200/img/wt/' + path,
      seriesName: s.s,
      numberStart: '',
      purchasePrice: s.px,
      cargoTypes: s.cg || [],
      _source: 'WTraffic',
      tonnage: s.m,
      _catalog: true,
    });
  }
  return catalog;
}
